-- Real-season demo data for the Demo Season picker (Overview onboarding for a logged-out
-- visitor, and 'Preview demo data' for a signed-in one). One row per (show, league type) --
-- researched once by hand (Wikipedia + show recap sites, not the paid wiki-sync/episode-research
-- connectors) and stored here so that research is never repeated. src/lib/game/demo-season-builder.ts
-- reads a row's `data` and derives a full LeagueState from it, at whichever episode the viewer has
-- scrubbed to -- the row itself never changes.
--
-- Survivor 40: Winners at War reuses the season already hardcoded in mock-state.ts (that file is
-- untouched and still what a brand-new mock-mode session boots into); this is a from-scratch
-- classic-draft rendition of the same real boot order, driven through the generic builder instead,
-- for consistency with the other two picker entries.
--
-- The Traitors US Season 4 and The Challenge: Spies, Lies & Allies are both real, sourced seasons
-- (cast, boot/banishment order, roles) -- see the PR/commit this shipped in for sources. Some
-- simplifications: The Challenge's pair-based early format and mid-season redemption returns are
-- collapsed to each person's single final exit episode, 6 of that season's ~36 entrants whose fates
-- weren't clearly sourced are left out rather than guessed at, and (both Traitors and Challenge)
-- a couple of early-boot castaways are left undrafted free agents so the fictional 3-player draft
-- divides evenly (SnakeDraftStrategy needs a uniform roster size per player).

CREATE TABLE demo_seasons (
  id TEXT PRIMARY KEY,
  show_id TEXT NOT NULL,
  league_type_id TEXT NOT NULL,
  name TEXT NOT NULL,
  episode_count INTEGER NOT NULL,
  data JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

